def load(self, source: Union[str, BytesIO]) -> List[Dict[str, Any]]:
    """
    Load and process a document using Tesseract OCR.
    Returns a list of pages, each containing:
    - content: The extracted text content
    - image: The original image (if vision_mode is True)

    Args:
        source: Either a file path or BytesIO stream

    Returns:
        List[Dict[str, Any]]: List of pages with content and optional images
    """
    if not self.can_handle(source):
        raise ValueError(f"Cannot handle source: {source}")

    try:
        # Process based on source type and format
        if isinstance(source, str):
            if is_pdf_stream(source):
                with open(source, 'rb') as file:
                    return self._process_pdf(file)
            else:
                # Single image file
                image = Image.open(source)
                return self._process_single_image(image, source)
        else:
            # BytesIO stream
            if is_pdf_stream(source):
                return self._process_pdf(source)
            else:
                image = Image.open(source)
                return self._process_single_image(image, source)

    except Exception as e:
        raise ValueError(f"Error processing document: {str(e)}")

def can_handle_vision(self, source: Union[str, BytesIO]) -> bool:
    """
    Checks if the loader can handle the source in vision mode.

    Args:
        source: Either a file path (str), URL, or a BytesIO stream

    Returns:
        bool: True if the loader can handle the source in vision mode
    """
    try:
        if isinstance(source, str):
            if self._is_url(source):
                return True  # URLs are always supported in vision mode
            ext = get_file_extension(source).lower()
            return ext in ['pdf', 'jpg', 'jpeg', 'png', 'tiff', 'bmp']
        elif isinstance(source, BytesIO):
            try:
                Image.open(source)
                return True
            except:
                # Try to load as PDF
                try:
                    pdfium.PdfDocument(source)
                    return True
                except:
                    return False
        return False
    except Exception:
        return False

def can_handle_paginate(self, source: Union[str, BytesIO]) -> bool:
    """
    Checks if the source supports pagination (e.g., PDF, PPT).

    Args:
        source: Either a file path (str) or a BytesIO stream

    Returns:
        bool: True if the source supports pagination
    """
    try:
        if isinstance(source, str):
            # For file paths, check the extension
            ext = get_file_extension(source).lower()
        else:
            # For BytesIO streams, use magic to detect mime type
            mime = magic.from_buffer(source.getvalue(), mime=True)
            source.seek(0)  # Reset stream position
            return mime == 'application/pdf'

        # List of extensions that support pagination
        return ext in ['pdf']
    except Exception:
        return False

def can_handle_vision(self, source: Union[str, io.BytesIO]) -> bool:
    """Check if this loader can handle the source in vision mode."""
    return self.config.vision_enabled and self.can_handle(source)

